#### Variation 2: Custom Aggregation Service

**Use Case**: Complex business logic, conditional calls, data enrichment

**Implementation**: Dedicated microservice deployed behind gateway

```javascript
// aggregation-service/src/handlers/providerDashboard.js
const express = require('express');
const axios = require('axios');
const CircuitBreaker = require('opossum');

// Circuit breakers for each backend service
const providerServiceBreaker = new CircuitBreaker(callProviderService, {
  timeout: 5000,
  errorThresholdPercentage: 50,
  resetTimeout: 30000
});

async function getProviderDashboard(req, res) {
  const { providerId } = req.params;
  const userContext = req.user; // From JWT token

  try {
    // Execute parallel calls with circuit breaker protection
    const [profile, credentialing, claims, payments, priorAuth] =
      await Promise.allSettled([
        providerServiceBreaker.fire(providerId),
        credentialingServiceBreaker.fire(providerId),
        claimsServiceBreaker.fire(providerId, { period: '30d' }),
        paymentsServiceBreaker.fire(providerId),
        priorAuthServiceBreaker.fire(providerId, { status: 'outstanding' })
      ]);

    // Build aggregated response with error handling
    const dashboard = {
      providerId,
      profile: profile.status === 'fulfilled' ? profile.value : { error: 'unavailable' },
      credentialing: credentialing.status === 'fulfilled' ? credentialing.value : { error: 'unavailable' },
      claimsStats: claims.status === 'fulfilled' ? claims.value : { error: 'unavailable' },
      payments: payments.status === 'fulfilled' ? payments.value : { error: 'unavailable' },
      priorAuth: priorAuth.status === 'fulfilled' ? priorAuth.value : { error: 'unavailable' },
      _metadata: {
        timestamp: new Date().toISOString(),
        partial: [profile, credentialing, claims, payments, priorAuth].some(r => r.status !== 'fulfilled')
      }
    };

    // Cache result
    await cacheService.set(`provider:dashboard:${providerId}`, dashboard, { ttl: 300 }); // 5 min

    res.json(dashboard);
  } catch (error) {
    logger.error({ error, providerId }, 'Dashboard aggregation failed');
    res.status(500).json({ error: 'Unable to load dashboard' });
  }
}
```

**Pros**: Full control, complex logic, testable, language flexibility
**Cons**: More infrastructure, deployment complexity, maintenance overhead

