#### Phase 2: Implementation (Weeks 3-6)

**Step 1: Implement Aggregation Logic**

**Option A: Azure APIM Policy-Based (Simple Aggregation)**

```xml
<!-- Azure APIM Policy -->
<policies>
    <inbound>
        <base />
        <set-variable name="providerId" value="@(context.Request.MatchedParameters["providerId"])" />
        <cache-lookup-value key="@("dashboard:" + context.Variables["providerId"])" variable-name="cachedDashboard" />
        <choose>
            <when condition="@(context.Variables.ContainsKey("cachedDashboard"))">
                <return-response>
                    <set-status code="200" />
                    <set-header name="X-Cache" exists-action="override">
                        <value>HIT</value>
                    </set-header>
                    <set-body>@((string)context.Variables["cachedDashboard"])</set-body>
                </return-response>
            </when>
        </choose>
    </inbound>
    <backend>
        <!-- Parallel backend calls -->
        <send-request mode="new" response-variable-name="profileResponse" timeout="5" ignore-error="false">
            <set-url>@($"https://provider-service.internal/providers/{context.Variables["providerId"]}")</set-url>
            <set-method>GET</set-method>
            <set-header name="Authorization" exists-action="override">
                <value>@(context.Request.Headers.GetValueOrDefault("Authorization",""))</value>
            </set-header>
        </send-request>

        <send-request mode="new" response-variable-name="credentialingResponse" timeout="5" ignore-error="true">
            <set-url>@($"https://credentialing-service.internal/credentialing/{context.Variables["providerId"]}/status")</set-url>
            <set-method>GET</set-method>
            <set-header name="Authorization" exists-action="override">
                <value>@(context.Request.Headers.GetValueOrDefault("Authorization",""))</value>
            </set-header>
        </send-request>

        <send-request mode="new" response-variable-name="claimsResponse" timeout="5" ignore-error="true">
            <set-url>@($"https://claims-service.internal/claims/statistics?providerId={context.Variables["providerId"]}&period=30d")</set-url>
            <set-method>GET</set-method>
            <set-header name="Authorization" exists-action="override">
                <value>@(context.Request.Headers.GetValueOrDefault("Authorization",""))</value>
            </set-header>
        </send-request>
    </backend>
    <outbound>
        <return-response>
            <set-status code="200" />
            <set-header name="Content-Type" exists-action="override">
                <value>application/json</value>
            </set-header>
            <set-header name="X-Cache" exists-action="override">
                <value>MISS</value>
            </set-header>
            <set-body>@{
                var profile = ((IResponse)context.Variables["profileResponse"]).Body.As<JObject>();
                var credentialing = context.Variables.ContainsKey("credentialingResponse") &&
                                  ((IResponse)context.Variables["credentialingResponse"]).StatusCode == 200
                    ? ((IResponse)context.Variables["credentialingResponse"]).Body.As<JObject>()
                    : new JObject(new JProperty("status", "unavailable"));
                var claims = context.Variables.ContainsKey("claimsResponse") &&
                           ((IResponse)context.Variables["claimsResponse"]).StatusCode == 200
                    ? ((IResponse)context.Variables["claimsResponse"]).Body.As<JObject>()
                    : new JObject(new JProperty("status", "unavailable"));

                var dashboard = new JObject(
                    new JProperty("providerId", context.Variables["providerId"]),
                    new JProperty("profile", profile),
                    new JProperty("credentialing", credentialing),
                    new JProperty("claimsStats", claims),
                    new JProperty("_metadata", new JObject(
                        new JProperty("timestamp", DateTime.UtcNow.ToString("o")),
                        new JProperty("partial", credentialing["status"]?.ToString() == "unavailable" ||
                                                 claims["status"]?.ToString() == "unavailable")
                    ))
                );

                return dashboard.ToString();
            }</set-body>
        </return-response>
        <cache-store-value key="@("dashboard:" + context.Variables["providerId"])" value="@(context.Response.Body.As<string>())" duration="300" />
    </outbound>
</policies>
```

**Option B: Custom Aggregation Service (Complex Logic)**

```javascript
// aggregation-service/src/handlers/providerDashboard.js
const express = require('express');
const axios = require('axios');
const CircuitBreaker = require('opossum');
const prom = require('prom-client');
const logger = require('../utils/logger');
const cacheService = require('../services/cacheService');

// Metrics
const aggregationDuration = new prom.Histogram({
  name: 'aggregation_duration_seconds',
  help: 'Duration of aggregation requests',
  labelNames: ['endpoint', 'status']
});

const backendCallDuration = new prom.Histogram({
  name: 'backend_call_duration_seconds',
  help: 'Duration of backend service calls',
  labelNames: ['service', 'status']
});

// Circuit breakers for backend services
const createServiceBreaker = (serviceName, serviceUrl) => {
  return new CircuitBreaker(async (path, options = {}) => {
    const timer = backendCallDuration.startTimer({ service: serviceName });
    try {
      const response = await axios.get(`${serviceUrl}${path}`, {
        timeout: options.timeout || 5000,
        headers: options.headers || {}
      });
      timer({ status: 'success' });
      return response.data;
    } catch (error) {
      timer({ status: 'error' });
      throw error;
    }
  }, {
    timeout: 5000,
    errorThresholdPercentage: 50,
    resetTimeout: 30000,
    name: serviceName
  });
};

const providerServiceBreaker = createServiceBreaker('provider-service', process.env.PROVIDER_SERVICE_URL);
const credentialingServiceBreaker = createServiceBreaker('credentialing-service', process.env.CREDENTIALING_SERVICE_URL);
const claimsServiceBreaker = createServiceBreaker('claims-service', process.env.CLAIMS_SERVICE_URL);
const paymentsServiceBreaker = createServiceBreaker('payments-service', process.env.PAYMENTS_SERVICE_URL);
const priorAuthServiceBreaker = createServiceBreaker('priorauth-service', process.env.PRIORAUTH_SERVICE_URL);

const router = express.Router();

router.get('/provider/dashboard', async (req, res) => {
  const timer = aggregationDuration.startTimer({ endpoint: 'provider-dashboard' });
  const { providerId } = req.query;
  const authHeader = req.headers.authorization;

  if (!providerId) {
    return res.status(400).json({ error: 'providerId is required' });
  }

  const traceId = req.headers['x-trace-id'] || `trace-${Date.now()}`;
  logger.info({ traceId, providerId }, 'Aggregating provider dashboard');

  try {
    // Check cache first
    const cacheKey = `provider:dashboard:${providerId}`;
    const cached = await cacheService.get(cacheKey);
    if (cached) {
      logger.info({ traceId, providerId }, 'Cache hit');
      timer({ status: 'cache-hit' });
      return res.set('X-Cache', 'HIT').json(cached);
    }

    // Execute parallel backend calls with circuit breaker protection
    const [profile, credentialing, claims, payments, priorAuth] = await Promise.allSettled([
      providerServiceBreaker.fire(`/providers/${providerId}`, {
        headers: { Authorization: authHeader, 'X-Trace-Id': traceId }
      }),
      credentialingServiceBreaker.fire(`/credentialing/${providerId}/status`, {
        headers: { Authorization: authHeader, 'X-Trace-Id': traceId }
      }),
      claimsServiceBreaker.fire(`/claims/statistics?providerId=${providerId}&period=30d`, {
        headers: { Authorization: authHeader, 'X-Trace-Id': traceId }
      }),
      paymentsServiceBreaker.fire(`/payments/summary?providerId=${providerId}`, {
        headers: { Authorization: authHeader, 'X-Trace-Id': traceId }
      }),
      priorAuthServiceBreaker.fire(`/prior-auth?providerId=${providerId}&status=outstanding`, {
        headers: { Authorization: authHeader, 'X-Trace-Id': traceId }
      })
    ]);

    // Build aggregated response with graceful degradation
    const dashboard = {
      providerId,
      profile: profile.status === 'fulfilled' ? profile.value : { status: 'unavailable', error: profile.reason?.message },
      credentialing: credentialing.status === 'fulfilled' ? credentialing.value : { status: 'unavailable', error: credentialing.reason?.message },
      claimsStats: claims.status === 'fulfilled' ? claims.value : { status: 'unavailable', error: claims.reason?.message },
      payments: payments.status === 'fulfilled' ? payments.value : { status: 'unavailable', error: payments.reason?.message },
      priorAuth: priorAuth.status === 'fulfilled' ? priorAuth.value : { status: 'unavailable', error: priorAuth.reason?.message },
      _metadata: {
        timestamp: new Date().toISOString(),
        traceId,
        partial: [profile, credentialing, claims, payments, priorAuth].some(r => r.status !== 'fulfilled'),
        failures: [
          profile.status === 'rejected' ? 'profile' : null,
          credentialing.status === 'rejected' ? 'credentialing' : null,
          claims.status === 'rejected' ? 'claims' : null,
          payments.status === 'rejected' ? 'payments' : null,
          priorAuth.status === 'rejected' ? 'priorAuth' : null
        ].filter(Boolean)
      }
    };

    // If critical service (profile) failed, return error
    if (profile.status === 'rejected') {
      logger.error({ traceId, providerId, error: profile.reason }, 'Critical service failure');
      timer({ status: 'error' });
      return res.status(503).json({
        error: 'Provider profile service unavailable',
        traceId
      });
    }

    // Cache result (5 minutes)
    await cacheService.set(cacheKey, dashboard, { ttl: 300 });

    logger.info({ traceId, providerId, partial: dashboard._metadata.partial }, 'Dashboard aggregation complete');
    timer({ status: dashboard._metadata.partial ? 'partial-success' : 'success' });

    const statusCode = dashboard._metadata.partial ? 206 : 200;
    res.set('X-Cache', 'MISS').status(statusCode).json(dashboard);
  } catch (error) {
    logger.error({ traceId, providerId, error }, 'Dashboard aggregation failed');
    timer({ status: 'error' });
    res.status(500).json({
      error: 'Unable to load dashboard',
      traceId
    });
  }
});

module.exports = router;
```

**Step 2: Configure Caching Strategy**

```javascript
// cacheService.js
const Redis = require('ioredis');
const redis = new Redis({
  host: process.env.REDIS_HOST,
  port: process.env.REDIS_PORT,
  password: process.env.REDIS_PASSWORD,
  tls: process.env.REDIS_TLS === 'true' ? {} : undefined,
  retryStrategy: (times) => Math.min(times * 50, 2000)
});

class CacheService {
  async get(key) {
    try {
      const value = await redis.get(key);
      return value ? JSON.parse(value) : null;
    } catch (error) {
      logger.error({ error, key }, 'Cache get failed');
      return null; // Fail open - continue without cache
    }
  }

  async set(key, value, options = {}) {
    const { ttl = 300 } = options; // Default 5 minutes
    try {
      await redis.setex(key, ttl, JSON.stringify(value));
    } catch (error) {
      logger.error({ error, key }, 'Cache set failed');
      // Don't throw - caching is not critical
    }
  }

  async del(key) {
    try {
      await redis.del(key);
    } catch (error) {
      logger.error({ error, key }, 'Cache delete failed');
    }
  }

  async invalidatePattern(pattern) {
    try {
      const keys = await redis.keys(pattern);
      if (keys.length > 0) {
        await redis.del(...keys);
      }
    } catch (error) {
      logger.error({ error, pattern }, 'Cache pattern invalidation failed');
    }
  }
}

module.exports = new CacheService();
```

**Step 3: Implement Error Handling and Resilience**

```javascript
// resilience.js - Circuit breaker event handlers
providerServiceBreaker.on('open', () => {
  logger.error({ service: 'provider-service' }, 'Circuit breaker opened');
  // Alert operations team
  alertService.send({
    severity: 'critical',
    message: 'Provider service circuit breaker opened',
    service: 'provider-service'
  });
});

providerServiceBreaker.on('halfOpen', () => {
  logger.info({ service: 'provider-service' }, 'Circuit breaker half-open, testing service');
});

providerServiceBreaker.on('close', () => {
  logger.info({ service: 'provider-service' }, 'Circuit breaker closed, service recovered');
});

// Fallback for circuit breaker
providerServiceBreaker.fallback(async (providerId) => {
  logger.warn({ providerId }, 'Using fallback for provider service');
  // Return cached data even if stale (up to 1 hour)
  const staleData = await cacheService.get(`provider:profile:${providerId}:stale`);
  if (staleData) {
    return { ...staleData, _stale: true };
  }
  throw new Error('No fallback data available');
});
```

