#### Phase 3: Testing and Validation (Weeks 7-8)

**Step 1: Unit Testing**

```javascript
// __tests__/providerDashboard.test.js
const request = require('supertest');
const app = require('../app');
const nock = require('nock');

describe('Provider Dashboard Aggregation', () => {
  beforeEach(() => {
    nock.cleanAll();
  });

  it('should aggregate data from all services successfully', async () => {
    // Mock backend services
    nock('https://provider-service.internal')
      .get('/providers/P123')
      .reply(200, { id: 'P123', name: 'Dr. Smith', npi: '1234567890' });

    nock('https://credentialing-service.internal')
      .get('/credentialing/P123/status')
      .reply(200, { status: 'active', expirationDate: '2026-12-31' });

    nock('https://claims-service.internal')
      .get('/claims/statistics')
      .query({ providerId: 'P123', period: '30d' })
      .reply(200, { totalClaims: 150, paidAmount: 45000 });

    const response = await request(app)
      .get('/api/v1/provider/dashboard')
      .query({ providerId: 'P123' })
      .set('Authorization', 'Bearer valid-token')
      .expect(200);

    expect(response.body.providerId).toBe('P123');
    expect(response.body.profile.name).toBe('Dr. Smith');
    expect(response.body.credentialing.status).toBe('active');
    expect(response.body.claimsStats.totalClaims).toBe(150);
    expect(response.body._metadata.partial).toBe(false);
  });

  it('should handle partial failures gracefully', async () => {
    nock('https://provider-service.internal')
      .get('/providers/P123')
      .reply(200, { id: 'P123', name: 'Dr. Smith' });

    nock('https://credentialing-service.internal')
      .get('/credentialing/P123/status')
      .reply(500); // Service failure

    nock('https://claims-service.internal')
      .get('/claims/statistics')
      .query({ providerId: 'P123', period: '30d' })
      .reply(200, { totalClaims: 150 });

    const response = await request(app)
      .get('/api/v1/provider/dashboard')
      .query({ providerId: 'P123' })
      .set('Authorization', 'Bearer valid-token')
      .expect(206); // Partial content

    expect(response.body.profile.name).toBe('Dr. Smith');
    expect(response.body.credentialing.status).toBe('unavailable');
    expect(response.body.claimsStats.totalClaims).toBe(150);
    expect(response.body._metadata.partial).toBe(true);
    expect(response.body._metadata.failures).toContain('credentialing');
  });

  it('should return error if critical service fails', async () => {
    nock('https://provider-service.internal')
      .get('/providers/P123')
      .reply(500); // Critical service failure

    await request(app)
      .get('/api/v1/provider/dashboard')
      .query({ providerId: 'P123' })
      .set('Authorization', 'Bearer valid-token')
      .expect(503);
  });

  it('should use cached data when available', async () => {
    // First request - cache miss
    nock('https://provider-service.internal')
      .get('/providers/P123')
      .reply(200, { id: 'P123', name: 'Dr. Smith' });

    const response1 = await request(app)
      .get('/api/v1/provider/dashboard')
      .query({ providerId: 'P123' })
      .set('Authorization', 'Bearer valid-token')
      .expect(200);

    expect(response1.headers['x-cache']).toBe('MISS');

    // Second request - cache hit (no backend calls)
    const response2 = await request(app)
      .get('/api/v1/provider/dashboard')
      .query({ providerId: 'P123' })
      .set('Authorization', 'Bearer valid-token')
      .expect(200);

    expect(response2.headers['x-cache']).toBe('HIT');
    expect(response2.body.providerId).toBe('P123');
  });
});
```

**Step 2: Performance Testing**

```javascript
// k6 load test script
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const errorRate = new Rate('errors');

export const options = {
  stages: [
    { duration: '2m', target: 100 }, // Ramp up to 100 users
    { duration: '5m', target: 100 }, // Stay at 100 users
    { duration: '2m', target: 500 }, // Ramp up to 500 users
    { duration: '5m', target: 500 }, // Stay at 500 users
    { duration: '2m', target: 0 },   // Ramp down
  ],
  thresholds: {
    http_req_duration: ['p(95)<2000'], // 95% of requests under 2s
    errors: ['rate<0.05'], // Error rate under 5%
  },
};

export default function () {
  const providerIds = ['P001', 'P002', 'P003', 'P004', 'P005'];
  const providerId = providerIds[Math.floor(Math.random() * providerIds.length)];

  const response = http.get(
    `https://api.gainwell.com/api/v1/provider/dashboard?providerId=${providerId}`,
    {
      headers: { Authorization: `Bearer ${__ENV.AUTH_TOKEN}` },
    }
  );

  const success = check(response, {
    'status is 200 or 206': (r) => r.status === 200 || r.status === 206,
    'response time < 2s': (r) => r.timings.duration < 2000,
    'has provider data': (r) => JSON.parse(r.body).profile !== undefined,
  });

  errorRate.add(!success);
  sleep(1);
}
```
